CREATE TABLE IF NOT EXISTS legal_knowledge_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_scope text NOT NULL, jurisdiction_id uuid, source_name text NOT NULL, source_type text NOT NULL, issuing_body text NOT NULL, source_url text, publication_date date, effective_date date, expiry_date date, authority_level text NOT NULL DEFAULT 'Official', reliability_score numeric(5,2), verification_status text NOT NULL DEFAULT 'Pending', source_summary text, retrieved_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS legal_knowledge_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid NOT NULL REFERENCES legal_knowledge_sources(id) ON DELETE CASCADE, rule_code text NOT NULL UNIQUE, rule_title text NOT NULL, rule_type text NOT NULL, domain_code text NOT NULL, statement text NOT NULL, applicability text NOT NULL DEFAULT 'Continental guidance', mandatory boolean NOT NULL DEFAULT false, confidence_score numeric(5,2), legal_force text NOT NULL DEFAULT 'Guidance', effective_from date, effective_to date, review_due date, status text NOT NULL DEFAULT 'Active', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jurisdiction_rule_bindings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rule_id uuid NOT NULL REFERENCES legal_knowledge_rules(id) ON DELETE CASCADE, jurisdiction_id uuid NOT NULL, binding_type text NOT NULL DEFAULT 'Reference', local_status text NOT NULL DEFAULT 'Unassessed', local_source_id uuid REFERENCES legal_knowledge_sources(id) ON DELETE SET NULL, local_rule_text text, local_effective_date date, local_review_due date, reviewer_reference text, confidence_score numeric(5,2), blocking boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'Pending', UNIQUE(rule_id,jurisdiction_id));
CREATE TABLE IF NOT EXISTS legal_rule_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rule_id uuid NOT NULL REFERENCES legal_knowledge_rules(id) ON DELETE CASCADE, jurisdiction_id uuid, review_type text NOT NULL, outcome text NOT NULL, reviewer_reference text, review_notes text, reviewed_at timestamptz NOT NULL DEFAULT now(), next_review_due date, evidence_reference text, status text NOT NULL DEFAULT 'Recorded');
CREATE INDEX IF NOT EXISTS idx_legal_sources_scope ON legal_knowledge_sources(source_scope,verification_status);
CREATE INDEX IF NOT EXISTS idx_legal_rules_domain ON legal_knowledge_rules(domain_code,status);
CREATE INDEX IF NOT EXISTS idx_rule_bindings_jurisdiction ON jurisdiction_rule_bindings(jurisdiction_id,local_status);
