INSERT INTO legal_knowledge_sources (source_scope,source_name,source_type,issuing_body,source_url,publication_date,authority_level,reliability_score,verification_status,source_summary) SELECT 'Continental','Framework and Guidelines on Land Policy in Africa','Policy framework','African Union','https://au.int/en/documents/20110131/framework-and-guidelines-land-policy-africa','2011-01-31','Official',98,'Verified','AU framework addressing land rights, tenure security and land governance in Africa.' WHERE NOT EXISTS (SELECT 1 FROM legal_knowledge_sources WHERE source_name='Framework and Guidelines on Land Policy in Africa');
