INSERT INTO legal_knowledge_sources (source_scope,source_name,source_type,issuing_body,source_url,publication_date,authority_level,reliability_score,verification_status,source_summary) SELECT 'Continental','Agreement Establishing the African Continental Free Trade Area','Treaty','African Union','https://au.int/en/african-continental-free-trade-area','2018-03-21','Official',99,'Verified','Continental treaty framework for African economic integration; does not replace national land or property law.' WHERE NOT EXISTS (SELECT 1 FROM legal_knowledge_sources WHERE source_name='Agreement Establishing the African Continental Free Trade Area');
INSERT INTO legal_knowledge_rules (source_id,rule_code,rule_title,rule_type,domain_code,statement,applicability,mandatory,confidence_score,legal_force) SELECT id,'AU-LAND-001','Protect and document the full bundle of land rights','Principle','LAND_RIGHTS','Asset diligence should identify statutory, customary and other relevant interests rather than treating registered title as the only possible interest.','Continental guidance',false,96,'Guidance' FROM legal_knowledge_sources WHERE source_name='Framework and Guidelines on Land Policy in Africa' AND NOT EXISTS (SELECT 1 FROM legal_knowledge_rules WHERE rule_code='AU-LAND-001');
INSERT INTO legal_knowledge_rules (source_id,rule_code,rule_title,rule_type,domain_code,statement,applicability,mandatory,confidence_score,legal_force) SELECT id,'AU-LAND-002','Treat customary tenure as a first-class diligence domain','Safeguard','CUSTOMARY_RIGHTS','Customary and community tenure should be identified, documented and assessed through participatory processes before an asset is represented as clear for transaction.','Continental guidance',false,96,'Guidance' FROM legal_knowledge_sources WHERE source_name='Framework and Guidelines on Land Policy in Africa' AND NOT EXISTS (SELECT 1 FROM legal_knowledge_rules WHERE rule_code='AU-LAND-002');
INSERT INTO legal_knowledge_rules (source_id,rule_code,rule_title,rule_type,domain_code,statement,applicability,mandatory,confidence_score,legal_force) SELECT id,'AU-LAND-003','Use participatory and consultative land administration','Governance principle','COMMUNITY_PROCESS','Material land-rights assessments should provide for transparent, participatory and consultative processes appropriate to the jurisdiction and affected rights-holders.','Continental guidance',false,95,'Guidance' FROM legal_knowledge_sources WHERE source_name='Land Governance Strategy' AND NOT EXISTS (SELECT 1 FROM legal_knowledge_rules WHERE rule_code='AU-LAND-003');
INSERT INTO legal_knowledge_rules (source_id,rule_code,rule_title,rule_type,domain_code,statement,applicability,mandatory,confidence_score,legal_force) SELECT id,'AU-LAND-004','Preserve evidence of land-rights provenance','Evidence rule','EVIDENCE','Every material land-rights conclusion should retain its source, issuing body, effective date and verification status so the conclusion can be challenged or refreshed.','ÒsánVault institutional control',true,98,'Platform control' FROM legal_knowledge_sources WHERE source_name='Framework and Guidelines on Land Policy in Africa' AND NOT EXISTS (SELECT 1 FROM legal_knowledge_rules WHERE rule_code='AU-LAND-004');
INSERT INTO legal_knowledge_rules (source_id,rule_code,rule_title,rule_type,domain_code,statement,applicability,mandatory,confidence_score,legal_force) SELECT id,'AU-CONT-001','Do not infer national property rights from continental integration instruments','Legal boundary','JURISDICTIONAL_SCOPE','Continental integration instruments inform cross-border institutional context but do not by themselves establish national land title, customary rights, licences or local approvals.','Continental guidance',true,99,'Platform control' FROM legal_knowledge_sources WHERE source_name='Agreement Establishing the African Continental Free Trade Area' AND NOT EXISTS (SELECT 1 FROM legal_knowledge_rules WHERE rule_code='AU-CONT-001');